-- 118: Worlds of Fun's removed coasters from Carter's RCDB screenshots,
-- 2026-10-31. The original Zambezi Zinger (Schwarzkopf Speed Racer, 1973-1997)
-- is "Zambezi Zinger (1973)" - the plain name is the 2023 GCI, like "Wild Mouse
-- (1958)" - and is linked to Montaña Rusa at Parque del Café (home), its next
-- stop. Also Extremeroller (Arrow Corkscrew 1976-1988; later Spiral at Formosa
-- Fun Coast, not a park here), Orient Express (Arrow looper 1980-2003),
-- Schussboomer (Schwarzkopf Wildcat 54m 1973-1984), Silly Serpent (Herschell
-- Little Dipper 1973-1987). Cosmic Coaster gets its 0:55. Safe to run twice.
UPDATE coasters SET inv = 0, dur = 55 WHERE name = 'Cosmic Coaster' AND park = 'Worlds of Fun' AND dur IS NULL;
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Montaña Rusa' AND h.park = 'Parque del Café' AND (c.id = h.id OR (c.name = 'Zambezi Zinger (1973)' AND c.park = 'Worlds of Fun'));
