INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Zambezi Zinger (1973)', 'Worlds of Fun', 'Steel', 'Schwarzkopf', NULL, 56.8, 41.2, 2583.0, 0, 151, 1973, '1973-05-26', 'day', '1997-10-12', 'day', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Zambezi Zinger (1973)' AND park = 'Worlds of Fun');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Zambezi Zinger (1973)' AND c.park = 'Worlds of Fun' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 2, json_object('id', id, 'fields', json_array('inv', 'dur'), 'via', '118') FROM coasters WHERE name = 'Cosmic Coaster' AND park = 'Worlds of Fun' AND dur IS NULL;
